import{_ as d,o as a,c as e,ag as r}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 4 章：不背产品参数，先看选择维度","description":"四组入门分类 + 六个辅助维度，教你用「需求卡」而非产品参数来选 Agent；账号稳定性是前置门槛。","frontmatter":{"title":"第 4 章：不背产品参数，先看选择维度","description":"四组入门分类 + 六个辅助维度，教你用「需求卡」而非产品参数来选 Agent；账号稳定性是前置门槛。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/04-how-to-choose.md","filePath":"guide/04-how-to-choose.md","lastUpdated":null}'),o={name:"guide/04-how-to-choose.md"};function l(i,t,n,h,s,u){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="第-4-章-不背产品参数-先看选择维度" tabindex="-1">第 4 章：不背产品参数，先看选择维度 <a class="header-anchor" href="#第-4-章-不背产品参数-先看选择维度" aria-label="Permalink to &quot;第 4 章：不背产品参数，先看选择维度&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>打开任何一款 Agent 的官网，你都会看到一堆参数：上下文长度、模型名称、Credits、套餐价格……<strong>零基础用户背这些毫无意义</strong>——因为参数不等于体验。本章教你反过来：先搞清楚<strong>你自己的需求</strong>，再拿需求去匹配产品。产出：一张<strong>个人 Agent 需求卡</strong>。第 5、6 章会拿这张卡直接去七款产品里选。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>我的一个朋友想买「最强」的 AI 产品，对比了一晚上参数表，最后因为「模型分数最高」选了一款海外产品。结果：注册需要海外支付方式，折腾两天没付成款，弃用。</p><p>另一个朋友选了参数表上「没那么亮眼」的国内产品，半小时跑通了第一个任务，现在每天都在用。</p><p><strong>参数不会告诉你「你能不能注册」「界面你顺不顺手」「它会不会偷偷读你的文件」。</strong> 这些才是新手真正要看的维度。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>先分四组建立直觉</strong>：海外综合型（Claude、Codex）、国内综合型（TraeWork、WorkBuddy）、代码优先型（Qoder、ZCode）、开源自主型（Hermes）。分组帮新手建立第一印象，<strong>不是能力排名</strong>；</li><li><strong>再用六个维度交叉判断</strong>：任务方向、开放程度、运行方式、自主程度、使用门槛、账号与地区稳定性；</li><li><strong>账号与地区稳定性是前置门槛</strong>：能力再强，注册不了、付不了款、账号被封，都是零（第 5 章 Claude 页就是活案例）；</li><li><strong>价格是最后看的</strong>，而且要看「单位、重置规则、活动期限」，不是只看「每月多少钱」；</li><li><strong>七款产品的实测结论见第 5、6 章</strong>——本章给你「需求卡」，下一章给你「产品证据」，第 6 章教你「怎么选」。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>四组分类</strong>（来自 <code>../../docs/06-agent-taxonomy.md</code>，选型辅助而非排名）：</li></ul><table tabindex="0"><thead><tr><th>分组</th><th>代表产品</th><th>看什么</th></tr></thead><tbody><tr><td>海外闭源托管型综合 Agent</td><td>Claude、Codex</td><td>综合能力、官方托管、服务边界</td></tr><tr><td>国内综合型 Agent</td><td>TraeWork 中国版、WorkBuddy</td><td>中文、本地化、上手便利</td></tr><tr><td>代码优先型 Agent</td><td>Qoder 中国版、ZCode 中国版</td><td>项目理解、代码修改、验证</td></tr><tr><td>开源自主型 Agent</td><td>Hermes Desktop</td><td>自由度、可定制、维护责任</td></tr></tbody></table><ul><li><strong>六个辅助维度</strong>：任务方向（办公/代码/设计/研究）、开放程度（源码/接口/模型开放度）、运行方式（云端/本地/自托管）、自主程度（每步确认 vs 连续执行）、使用门槛（零基础 GUI 可否）、账号与服务稳定性（能否注册、付费、申诉）。</li><li><strong>BYOK（自带密钥）</strong>：在 Agent 里填自己的 API Key，由模型供应商直接计费。白话解释：不买产品套餐，自己租「模型算力」插进去。它带来自由，也带来配置与账单管理成本。</li></ul><h2 id="跟着做-制作你的需求卡" tabindex="-1">跟着做：制作你的需求卡 <a class="header-anchor" href="#跟着做-制作你的需求卡" aria-label="Permalink to &quot;跟着做：制作你的需求卡&quot;">​</a></h2><h3 id="第一步-回答八个问题" tabindex="-1">第一步：回答八个问题 <a class="header-anchor" href="#第一步-回答八个问题" aria-label="Permalink to &quot;第一步：回答八个问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>我的答案</th></tr></thead><tbody><tr><td>1</td><td>我的三个主要任务是什么？（从序章任务延伸）</td><td></td></tr><tr><td>2</td><td>必须支持的文件或工具？</td><td></td></tr><tr><td>3</td><td>我所在地区、可用支付方式？</td><td></td></tr><tr><td>4</td><td>能接受的月度预算？</td><td></td></tr><tr><td>5</td><td>能否接受云端处理资料？</td><td></td></tr><tr><td>6</td><td>能否处理 API Key、模型供应商和环境配置？</td><td></td></tr><tr><td>7</td><td>账号中断时允许损失多少历史记录和时间？</td><td></td></tr><tr><td>8</td><td>我更看重：省心 / 便宜 / 透明 / 自由？（选两个）</td><td></td></tr></tbody></table><h3 id="第二步-把答案翻译成「筛选条件」" tabindex="-1">第二步：把答案翻译成「筛选条件」 <a class="header-anchor" href="#第二步-把答案翻译成「筛选条件」" aria-label="Permalink to &quot;第二步：把答案翻译成「筛选条件」&quot;">​</a></h3><ul><li>第 3 题答「只有国内支付」→ 排除海外付费产品；</li><li>第 5 题答「不能接受资料出境」→ 排除海外托管产品；</li><li>第 6 题答「不想碰 API」→ 排除 BYOK 主推产品（ZCode、Hermes 默认路径）；</li><li>第 7 题答「账号不能出事」→ 把账号稳定性列为硬条件；</li><li>第 8 题决定你最终比较时最看重哪两个维度（如「省心 + 透明」）。</li></ul><h3 id="第三步-写下候选清单" tabindex="-1">第三步：写下候选清单 <a class="header-anchor" href="#第三步-写下候选清单" aria-label="Permalink to &quot;第三步：写下候选清单&quot;">​</a></h3><p>先不追求精确，写下 2–4 款你觉得符合的候选，<strong>带着需求卡去读第 5 章对应产品页和第 6 章选择表</strong>。</p><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><p>我的需求卡（可对照第 6 章个人选型结论页）：</p><ul><li>主要任务：教程写作（文档）、代码项目、跨工具资料整理 → 综合型 + 代码型都要考虑；</li><li>支付：国内支付为主 → 国内产品优先，海外产品需评估；</li><li>预算：中，可订阅但不接受不可控成本；</li><li>资料边界：可云端，但重视「是否越权读取」；</li><li>配置能力：能配 API → BYOK 不排除，但优先级靠后；</li><li>最看重：省心 + 透明（变更可核对）。</li></ul><p>筛选结果：WorkBuddy、Codex 进入主候选（对应第 6 章结论）。注意：<strong>我的权重是「边界安全 + 变更透明」，如果你的权重是「最快最省」，结论会不同</strong>——这正是需求卡存在的意义。</p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>按模型分数选产品</td><td>把模型能力当产品能力</td><td>回到六个维度；模型只是五块拼图之一</td></tr><tr><td>看参数表比较上下文长度</td><td>参数 ≠ 体验</td><td>实测里没人量上下文，量的是「任务能不能一次过」</td></tr><tr><td>被「新用户福利」吸引注册</td><td>没看活动期限与适用产品线</td><td>对照 <code>docs/07</code>：很多福利已截止或属于别的产品线</td></tr><tr><td>海外产品付不了款</td><td>没先查支付方式</td><td>需求卡第 3 题先答，别等注册时才发现</td></tr><tr><td>账号被封才想起风险</td><td>没做前置检查</td><td>把「账号与地区稳定性」列为硬门槛（第 5 章 Claude 页）</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>注册任何产品前，确认它处理你资料的<strong>数据政策</strong>与你的组织/公司合规要求；</li><li>不要把公司机密、客户数据放进未获授权的工具；</li><li>「免费」最贵：看清免费额度的单位、重置周期、模型限制与活动期限（<code>docs/07</code> 有逐款核验表）。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>20 分钟：完成需求卡八问 → 翻译成筛选条件 → 写下 2–4 款候选 → 去第 5 章对应页面读「一句话结论」和「适合与不适合」，验证你的候选是否成立。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>个人 Agent 需求卡</strong>：八问答案 + 筛选条件 + 候选清单（这是第 6 章选择路径的输入）。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>四组分类建立直觉，不排名；</li><li>六个维度交叉判断，需求卡是工具；</li><li>账号与地区稳定性是前置门槛；</li><li>价格看单位、重置与期限，不只看金额；</li><li>需求卡 + 第 5 章证据 + 第 6 章路径 = 你的选择。</li></ol>',34)])])}const b=d(o,[["render",l]]);export{g as __pageData,b as default};
